import pytest


def key_match_paged(key0: list[int], key1: list[int], page_size: int) -> int:
    """Return the common-prefix length, rounded down to whole pages.

    This mirrors ``RadixKey.match(..., page_size=...)`` for non-bigram keys:
    only complete pages of matching tokens count, and a partial or incomplete
    trailing page is ignored.
    """
    if page_size < 1:
        raise ValueError("page_size must be >= 1")

    limit = min(len(key0), len(key1))
    matched = 0
    while matched < limit and key0[matched] == key1[matched]:
        matched += 1

    return (matched // page_size) * page_size


def test_mismatch_within_trailing_page():
    assert key_match_paged([1, 2, 3, 4, 5], [1, 2, 3, 9, 5], 2) == 2


def test_mismatch_on_page_boundary():
    assert key_match_paged([1, 2, 3, 4, 5], [1, 2, 9, 4, 5], 2) == 2


def test_page_size_one_counts_each_matching_token():
    assert key_match_paged([1, 2, 3, 4], [1, 2, 9, 4], 1) == 2


def test_shorter_key_limits_the_match():
    assert key_match_paged([1, 2, 3, 4, 5], [1, 2, 3], 2) == 2
    assert key_match_paged([1, 2], [1, 2, 3], 2) == 2


def test_identical_keys_match_all_complete_pages():
    assert key_match_paged([1, 2, 3, 4, 5, 6], [1, 2, 3, 4, 5, 6], 3) == 6


def test_empty_or_disjoint_keys_match_zero():
    assert key_match_paged([], [], 4) == 0
    assert key_match_paged([1, 2, 3], [], 2) == 0
    assert key_match_paged([9, 2, 3], [1, 2, 3], 2) == 0


def test_page_size_larger_than_common_prefix():
    assert key_match_paged([1, 2, 3], [1, 2, 3], 4) == 0


def test_invalid_page_size():
    with pytest.raises(ValueError):
        key_match_paged([1], [1], 0)
